#!/usr/bin/env node
'use strict';
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),cp=require('node:child_process'),zlib=require('node:zlib');
const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const read=p=>fs.readFileSync(p);
const REV='99daaf1b36f81e5b81dc6aa29d500b2f554a0a11',BASE='f9f9f10ae2513ec431568be2239b38b13435ac26';
const DATA_SHA='72f20c169b8466c6c02b3b0a689854f80d6f5c116455201234732359850cf7cc';
const DATA='';
function output(args){return cp.execFileSync(args[0],args.slice(1),{encoding:'utf8',stdio:['ignore','pipe','pipe'],timeout:30000,maxBuffer:8*1024*1024}).trim();}
function assertPath(file, root) {
  if(!file.startsWith(root+'/')) throw Error('Destination outside scope');
  for(let p=file;;p=path.dirname(p)) {
    if(fs.existsSync(p) && fs.lstatSync(p).isSymbolicLink()) throw Error('Symlink destination');
    if(p===root) break;
  }
}
function transaction(backup) {
  const rows=[];
  return {
    put(file,data,root,mode=0o644) {
      assertPath(file,root);
      const exists=fs.existsSync(file), old=exists?read(file):null;
      if(old && sha(old)===sha(data)) return;
      const stat=exists?fs.statSync(file):null, saved=path.join(backup,'file-'+rows.length);
      if(old) fs.writeFileSync(saved,old,{mode:0o600});
      fs.mkdirSync(path.dirname(file),{recursive:true});
      const tmp=file+'.pr101-'+crypto.randomBytes(5).toString('hex');
      fs.writeFileSync(tmp,data,{mode:stat?(stat.mode&0o777):mode});
      if(stat) fs.chownSync(tmp,stat.uid,stat.gid);
      const row={file,before:old?sha(old):null,after:sha(data),saved,stat};
      // Journal before rename, so a failed write never escapes rollback.
      rows.push(row);fs.renameSync(tmp,file);
    },
    rollback() {
      for(const row of [...rows].reverse()) {
        const current=fs.existsSync(row.file)?sha(read(row.file)):null;
        if(current===row.before) continue;
        if(current!==row.after) throw Error('Later modification prevents rollback');
        if(row.before===null) fs.unlinkSync(row.file);
        else {fs.writeFileSync(row.file,read(row.saved));fs.chmodSync(row.file,row.stat.mode);fs.chownSync(row.file,row.stat.uid,row.stat.gid);}
      }
    },
    verify() {for(const row of rows) if(sha(read(row.file))!==row.after) throw Error('Final file mismatch');},
    changed() {return rows.length>0;}
  };
}

function checkedLog(file,revision){const log=fs.readFileSync(file,'utf8');if(!log.includes('EXIT_CODE=0')||!log.includes('REVISION='+revision))throw Error('Expected successful previous deployment');return log;}
async function main(){
 if(process.getuid()!==0||Number(process.versions.node.split('.')[0])<22)throw Error('Run as root with Node 22+');
 const gzip=Buffer.from(DATA,'base64');if(sha(gzip)!==DATA_SHA)throw Error('Embedded package checksum mismatch');
 const pkg=JSON.parse(zlib.gunzipSync(gzip,{maxOutputLength:16*1024*1024}));
 if(pkg.revision!==REV||pkg.base!==BASE)throw Error('Unexpected source revision');
 const names=new Set();for(const row of pkg.files){
  if(!/^[A-Za-z0-9_.@/-]+$/.test(row.file)||row.file.split('/').some(x=>!x||x==='.'||x==='..')||!row.file.startsWith('dist/')||names.has(row.file))throw Error('Unsafe frontend scope');
  names.add(row.file);if(row.data!==null){row.data=Buffer.from(row.data,'utf8');if(sha(row.data)!==row.sha256)throw Error('Frontend file checksum mismatch');}
 }
 const entry=pkg.files.find(x=>x.file==='dist/index.html'),timeChunk=pkg.files.find(x=>/^dist\/assets\/commentTime-[\w-]+\.js$/.test(x.file));
 if(!entry||!timeChunk||!timeChunk.data.toString().includes('Asia/Shanghai'))throw Error('Missing comment timezone fix');
 const map=Buffer.from(pkg.styles.data,'base64');if(sha(map)!==pkg.styles.sha256)throw Error('Preload map checksum mismatch');
 const styles=JSON.parse(map);for(const block of Object.values(styles))for(const asset of [...block.css,...block.js])if(!names.has('dist'+asset))throw Error('Incomplete preload dependency closure');
 const us=fs.existsSync('/opt/mooncci-reader/current');let web,baseIndex,baseStyles,baseDir;
 if(us){
  const release=fs.realpathSync('/opt/mooncci-reader/current');if(!release.startsWith('/opt/mooncci-reader/releases/'))throw Error('Unexpected overseas reader release');web=release+'/dist';
  const log=checkedLog('/tmp/mooncci-pr101-edge-us.log',BASE),backup=log.match(/^BACKUP=(.+)$/m)?.[1];
  if(!backup||!/^\/www\/backup\/mooncci-pr101-edge-[A-Za-z0-9]+$/.test(backup))throw Error('Unexpected reader baseline');baseDir=backup+'/package/dist';baseIndex=fs.readFileSync(baseDir+'/index.html');
 }else{
  web='/www/wwwroot/mooncci.site';const log=checkedLog('/tmp/mooncci-pr101-main.log',BASE),stage=log.match(/^BUILD_STAGE=(.+)$/m)?.[1];
  if(!stage||!/^\/www\/wwwroot\/\.mooncci-pr101-build-[A-Za-z0-9]+$/.test(stage)||fs.realpathSync(stage)!==stage)throw Error('Unexpected primary baseline');
  baseDir=stage+'/dist';baseIndex=fs.readFileSync(baseDir+'/index.html');baseStyles=fs.readFileSync(stage+'/server/runtime/styles.json');
  if(JSON.stringify(JSON.parse(baseStyles).index.css)!==JSON.stringify(styles.index.css))throw Error('Unexpected entry CSS change');
  if(sha(fs.readFileSync('/www/wwwroot/mooncci-source/server/runtime/home.css'))!==pkg.homeCssSha)throw Error('Home SSR CSS differs from verified unchanged baseline');
  const health=await fetch('http://127.0.0.1:3001/api/health',{signal:AbortSignal.timeout(3000)});if(!health.ok||(await health.json()).ok!==true)throw Error('Primary API health failed');
 }
 for(const row of pkg.files){const file=web+'/'+row.file.slice(5);assertPath(file,web);if((row.data===null||!/\.(js|json|html)$/.test(row.file))&&(!fs.existsSync(file)||sha(fs.readFileSync(file))!==row.sha256))throw Error('Static CSS/image/font drift: '+row.file);}
 const liveEntry=sha(fs.readFileSync(web+'/index.html'));if(![sha(baseIndex),entry.sha256].includes(liveEntry))throw Error('Frontend index changed since the verified previous release');
 const mapFile='/www/wwwroot/mooncci-source/server/runtime/styles.json';if(!us&&![sha(baseStyles),pkg.styles.sha256].includes(sha(fs.readFileSync(mapFile))))throw Error('SSR preload map drift');
 fs.mkdirSync('/www/backup',{recursive:true});const backup=fs.mkdtempSync('/www/backup/mooncci-comment-time-');fs.chmodSync(backup,0o700);console.log('MODE='+(us?'us':'main')+'\nBACKUP='+backup);
 const tx=transaction(backup);
 try{
  if(sha(fs.readFileSync(web+'/index.html'))!==liveEntry)throw Error('Frontend entry changed concurrently');
  for(const row of pkg.files.filter(x=>x.file!=='dist/index.html'&&x.data!==null)){
   const file=web+'/'+row.file.slice(5);if(/\/assets\/.*\.(js|css)$/.test(file)&&fs.existsSync(file)&&sha(fs.readFileSync(file))!==row.sha256)throw Error('Immutable asset collision');tx.put(file,row.data,web);
  }
  if(!us)tx.put(mapFile,map,path.dirname(mapFile));
  tx.put(web+'/index.html',entry.data,web);tx.verify();
  for(const row of pkg.files)if(sha(fs.readFileSync(web+'/'+row.file.slice(5)))!==row.sha256)throw Error('Published frontend checksum mismatch');
  const curl=['curl','--noproxy','*','-fsS','--max-time','15','--resolve','mooncci.site:443:127.0.0.1'];
  const served=cp.execFileSync(curl[0],[...curl.slice(1),'https://mooncci.site/'+timeChunk.file.slice(5)],{maxBuffer:1024*1024});if(sha(served)!==timeChunk.sha256)throw Error('Public comment timezone chunk verification failed');
  if(!us){const html=output([...curl,'https://mooncci.site/article/18?comment_time_verify='+Date.now()]);const script=entry.data.toString().match(/src="(\/assets\/index-[^"]+\.js)"/)?.[1];if(!script||!html.includes(script)||!html.includes('mooncci-document-data'))throw Error('Public article SSR/entry verification failed');}
 }catch(error){try{tx.rollback();console.error('ROLLBACK=PASS');}catch{throw Error('Rollback requires attention; original files are in the root-only backup');}throw error;}
 console.log('PASS: comment dates and admin timestamps now use Beijing time; existing comments retained.\nREVISION='+REV+'\nEXIT_CODE=0');
}
module.exports={main};
if(require.main===module){
 if(process.argv.includes('--lock-held'))main().catch(e=>{console.error('STOPPED: '+e.message+'\nEXIT_CODE=1');process.exitCode=1;});
 else{fs.mkdirSync('/www/backup',{recursive:true});const result=cp.spawnSync('flock',['-w','10','/www/backup/mooncci-deploy.lock',process.execPath,__filename,'--lock-held'],{stdio:'inherit'});process.exitCode=result.status??1;}
}
